function linkFor(story){return prefix+(storyPage?'':'stories/')+'story-'+story.id+'.html';}
function coverFor(story){return prefix+'images/'+story.cover+'?v=cover-refresh-3';}
function escapeHTML(value){return String(value).replace(/[&<>\"']/g,function(character){return {'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[character];});}
function profileHash(value){let hash=5381;for(let index=0;index<value.length;index+=1){hash=(hash*33)^value.charCodeAt(index);}return String(hash>>>0);}
function readerProfiles(){const saved=STORE.get(PROFILE_KEY,[]);return Array.isArray(saved)?saved:[];}
function currentReader(){const id=STORE.get(ACTIVE_PROFILE_KEY,'');return readerProfiles().find(function(profile){return profile.id===id;})||null;}
function readerStoreKey(type){const reader=currentReader();return reader?'koma-reader-'+reader.id+'-'+type:'';}
function liked(){const key=readerStoreKey('liked');return key?STORE.get(key,[]):[];}
function read(){const key=readerStoreKey('read');return key?STORE.get(key,[]):[];}
function isLiked(id){return liked().indexOf(id)!==-1;}
function active(name){return page===name||(page==='story'&&name==='browse')?'is-active':'';}

function renderChrome(){
 const links=[['home','Home','index.html','home'],['browse','Browse','browse.html','browse'],['genres','Genres','genres.html','genres'],['shelf','Shelf','shelf.html','shelf'],['about','About','about.html','about']];
 const header=one('[data-site-header]'),mobile=one('[data-mobile-nav]'),footer=one('[data-site-footer]');
 const reader=currentReader();const readerLabel=reader?'Reader: '+escapeHTML(reader.name):'Reader login';
 const night=document.documentElement.dataset.theme==='night';
 if(header){header.innerHTML='<div class="header-inner"><a class="brand" href="'+prefix+'index.html" aria-label="KOMA home"><span>KOMA</span><small>コマ</small></a><nav class="desktop-nav" aria-label="Main navigation">'+links.map(function(item){const selected=active(item[0]);return '<a class="nav-link '+selected+'" href="'+prefix+item[2]+'" '+(selected?'aria-current="page"':'')+'>'+item[1]+'</a>';}).join('')+'</nav><div class="header-actions"><button class="reader-chip" type="button" data-profile-open>'+icon.user+'<span>'+readerLabel+'</span></button><button class="theme-toggle" type="button" data-theme-toggle aria-label="Switch to '+(night?'light':'dark')+' theme" aria-pressed="'+night+'">'+(night?icon.sun:icon.moon)+'</button></div></div>';}
 if(mobile){mobile.innerHTML=links.map(function(item){const selected=active(item[0]);return '<a class="mobile-tab '+selected+'" href="'+prefix+item[2]+'" '+(selected?'aria-current="page"':'')+'>'+icon[item[3]]+'<span>'+item[1]+'</span></a>';}).join('');}
 if(footer){footer.innerHTML='<div class="footer-grid"><div class="footer-brand"><p class="footer-title">KOMA <span>/ コマ</span></p><p>A curated manga discovery shelf built around covers, moods, and thoughtful browsing.</p></div><nav class="footer-links" aria-label="Footer navigation">'+links.slice(0,4).map(function(item){return '<a href="'+prefix+item[2]+'">'+item[1]+'</a>';}).join('')+'</nav><div class="footer-owner"><p class="footer-label">A student-built digital library</p><p><strong>Sachi DelaCruz</strong><br>BSIT 21010 · Bestlink College of the Philippines<br>ITE Project · 2nd Year · © 2026</p></div></div><div class="footer-legal">Cover art © its respective owners. Educational use only. Reading links lead to official sources.</div>';}
 if(!one('#reader-modal')){const readerModal=document.createElement('div');readerModal.className='modal reader-modal';readerModal.id='reader-modal';readerModal.hidden=true;document.body.appendChild(readerModal);}
 if(!one('[data-scroll-progress]')){const progress=document.createElement('div');progress.className='scroll-progress';progress.dataset.scrollProgress='';progress.setAttribute('aria-hidden','true');document.body.appendChild(progress);}
 if(!one('[data-scroll-dock]')){const dock=document.createElement('nav');dock.className='scroll-dock';dock.dataset.scrollDock='';dock.setAttribute('aria-label','Page shortcuts');dock.innerHTML='<button class="scroll-jump" type="button" data-scroll-top aria-label="Scroll to top" title="Back to top" hidden>'+icon.arrowUp+'<span>Top</span></button><button class="scroll-jump" type="button" data-scroll-bottom aria-label="Scroll to bottom" title="Jump to bottom" hidden>'+icon.arrowDown+'<span>End</span></button>';document.body.appendChild(dock);}
}

function card(story){
 const likedClass=isLiked(story.id)?'is-liked':'';
 const available=story.hasChapter?'is-available':'is-pending';
 const label=story.hasChapter?'Chapter 01 live':'Discovery only';
 return '<article class="story-card" data-reveal><a class="cover-link" href="'+linkFor(story)+'" aria-label="View '+story.title+' details"><img src="'+coverFor(story)+'" alt="'+story.title+' manga cover" width="600" height="900" loading="lazy">'+(story.hasChapter?'<span class="feature-badge">READ NOW</span>':'')+'<span class="card-index">'+story.id+'</span></a><div class="card-copy"><div class="card-meta"><span class="tag">'+story.genre+'</span><span class="availability '+available+'">'+label+'</span></div><h3><a href="'+linkFor(story)+'">'+story.title+'</a></h3><p class="byline">'+story.author+'</p><div class="card-actions"><button class="like-button '+likedClass+'" type="button" data-like="'+story.id+'" aria-pressed="'+isLiked(story.id)+'" aria-label="'+(isLiked(story.id)?'Unlike ':'Like ')+story.title+'">'+icon.heart+'<span>'+(isLiked(story.id)?'Saved':'Save')+'</span></button><button class="text-button" type="button" data-details="'+story.id+'">Quick look</button><a class="card-arrow" href="'+linkFor(story)+'" aria-label="Open '+story.title+'">'+icon.arrow+'</a></div></div></article>';
}

function renderHome(){
 const root=one('[data-home]');if(!root)return;const feature=KOMA_STORIES[0];
 const groupCards=groups().slice(1).map(function(group,index){const titles=KOMA_STORIES.filter(function(story){return story.group===group;});return '<a class="mood-tile mood-tile--'+(index+1)+'" href="browse.html?genre='+encodeURIComponent(group)+'" data-reveal><span class="mood-number">0'+(index+1)+'</span><div><span class="eyebrow">'+titles.length+' titles</span><h3>'+group+'</h3><p>'+['Fast, strange, and impossible to put down.','Quiet feelings, sharp drama, real connection.','Big worlds, strange rules, one more chapter.'][index]+'</p></div><span class="mood-arrow">'+icon.arrow+'</span></a>';}).join('');
 root.innerHTML='<section class="hero" aria-labelledby="hero-title"><div class="hero-copy" data-reveal><span class="edition-mark">KOMA INDEX <b>01</b></span><p class="kicker">Curated manga discovery</p><h1 id="hero-title">Find your<br><em>next panel.</em></h1><p class="hero-lede">Thirty standout manga, organized for the way you actually browse: by energy, mood, and the cover that refuses to let you scroll past.</p><div class="button-row"><a class="button button--ink" href="browse.html">Explore the library '+icon.arrow+'</a><a class="button button--quiet" href="'+linkFor(feature)+'">Meet Dandadan</a></div><dl class="hero-stats"><div><dt>30</dt><dd>curated titles</dd></div><div><dt>03</dt><dd>mood shelves</dd></div><div><dt>01</dt><dd>official chapter</dd></div></dl></div><article class="feature-panel" data-reveal><a class="feature-visual" href="'+linkFor(feature)+'"><img src="'+coverFor(feature)+'" alt="Dandadan manga cover" width="600" height="900" fetchpriority="high"><span class="feature-stamp">FEATURED<br>CHAPTER 01</span></a><div class="feature-copy"><div><span class="eyebrow">This week\'s lead</span><h2>Dandadan</h2><p>Paranormal chaos, teenage nerve, and zero quiet moments.</p></div><a class="round-link" href="'+linkFor(feature)+'" aria-label="Open Dandadan">'+icon.arrow+'</a></div></article></section><section class="signal-strip" aria-label="KOMA library highlights"><div class="signal-track"><span>CURATED, NOT CLUTTERED</span><i>✦</i><span>30 STORIES</span><i>✦</i><span>OFFICIAL LINKS ONLY</span><i>✦</i><span>BUILD YOUR SHELF</span><i>✦</i><span>CURATED, NOT CLUTTERED</span><i>✦</i><span>30 STORIES</span><i>✦</i></div></section><section class="home-section" aria-labelledby="fresh-title"><div class="section-heading"><div><span class="section-index">01 / DISCOVER</span><h2 id="fresh-title">Fresh on the shelf</h2></div><a class="section-link" href="browse.html">View all 30 '+icon.arrow+'</a></div><div class="card-row">'+KOMA_STORIES.slice(0,8).map(card).join('')+'</div></section><section class="home-section" aria-labelledby="mood-title"><div class="section-heading"><div><span class="section-index">02 / FIND YOUR LANE</span><h2 id="mood-title">Browse by mood</h2></div><p>Three shelves. No endless scrolling.</p></div><div class="mood-grid">'+groupCards+'</div></section><section class="library-cta" data-reveal><span class="eyebrow">Your personal reading corner</span><h2>Save the stories that stay with you.</h2><p>Create a local reader profile and keep a private shelf of likes and completed reads on this device.</p><div class="button-row"><button class="button button--spot" type="button" data-profile-open>Open reader profile</button><a class="button button--quiet" href="shelf.html">View my shelf</a></div></section>';
 observeReveals();
}
function groups(){return ['All'].concat(Array.from(new Set(KOMA_STORIES.map(function(story){return story.group;}))));}

function renderBrowse(){
 const root=one('[data-browse]');if(!root)return;const asked=new URLSearchParams(location.search).get('genre')||'All';let selected=groups().indexOf(asked)!==-1?asked:'All';
 root.innerHTML='<section class="page-intro" data-reveal><span class="section-index">LIBRARY / ALL TITLES</span><p class="kicker">Thirty stories, zero filler</p><h1 class="page-title">Browse the shelf.</h1><p>Search by title or creator, filter by mood, then save anything that catches your eye.</p></section><section class="filter-shell" aria-label="Story filters"><div class="filter-top"><label class="search-box" for="story-search">'+icon.search+'<span class="sr-only">Search titles or authors</span><input id="story-search" class="search-field" type="search" placeholder="Search title or creator" autocomplete="off"></label><label class="sort-box"><span>Sort</span><select data-sort aria-label="Sort manga"><option value="featured">Curated</option><option value="title">Title A–Z</option><option value="author">Creator A–Z</option></select></label></div><div class="filter-row" data-genre-filters>'+groups().map(function(group){return '<button type="button" class="filter-chip '+(group===selected?'is-active':'')+'" data-filter="'+group+'" aria-pressed="'+(group===selected)+'">'+group+'</button>';}).join('')+'</div></section><div class="results-bar"><p data-result-count></p><button class="text-button" type="button" data-clear-filters hidden>Clear filters</button></div><div class="story-grid" data-browse-grid></div><div class="empty-state" data-empty hidden><strong>No panels found.</strong><span>Try a different title, creator, or mood.</span><button class="button" type="button" data-empty-reset>Reset search</button></div>';
 const search=one('#story-search'),sort=one('[data-sort]'),grid=one('[data-browse-grid]'),empty=one('[data-empty]'),count=one('[data-result-count]'),clear=one('[data-clear-filters]');
 function update(){const term=search.value.trim().toLowerCase();let found=KOMA_STORIES.filter(function(story){return (selected==='All'||story.group===selected)&&(story.title+' '+story.author+' '+story.genre).toLowerCase().indexOf(term)!==-1;});if(sort.value==='title')found=found.slice().sort(function(a,b){return a.title.localeCompare(b.title);});if(sort.value==='author')found=found.slice().sort(function(a,b){return a.author.localeCompare(b.author);});grid.innerHTML=found.map(card).join('');empty.hidden=found.length!==0;count.textContent=found.length+' of '+KOMA_STORIES.length+' titles · '+(selected==='All'?'All moods':selected);clear.hidden=selected==='All'&&!term&&sort.value==='featured';observeReveals();}
 function reset(){selected='All';search.value='';sort.value='featured';all('[data-filter]').forEach(function(item){const on=item.dataset.filter==='All';item.classList.toggle('is-active',on);item.setAttribute('aria-pressed',on);});update();}
 one('[data-genre-filters]').addEventListener('click',function(event){const button=event.target.closest('[data-filter]');if(!button)return;selected=button.dataset.filter;all('[data-filter]').forEach(function(item){const on=item===button;item.classList.toggle('is-active',on);item.setAttribute('aria-pressed',on);});update();});search.addEventListener('input',update);sort.addEventListener('change',update);clear.addEventListener('click',reset);one('[data-empty-reset]').addEventListener('click',reset);update();observeReveals();
}

function renderGenres(){
 const root=one('[data-genres]');if(!root)return;const set=groups().slice(1);
 root.innerHTML='<section class="page-intro" data-reveal><span class="section-index">LIBRARY / MOOD INDEX</span><p class="kicker">Pick a shelf</p><h1 class="page-title">Choose your energy.</h1><p>Skip the algorithm. Start with the kind of story you want tonight.</p></section><section class="genre-index" aria-label="Genre index">'+set.map(function(group,index){const titles=KOMA_STORIES.filter(function(story){return story.group===group;});return '<a class="genre-row genre-row--'+(index+1)+'" href="browse.html?genre='+encodeURIComponent(group)+'" data-reveal><span class="number">0'+(index+1)+'</span><span class="genre-name">'+group+'<small>'+['Fights, curses, monsters, and beautifully bad decisions.','Romance, ambition, ordinary days, and complicated hearts.','New worlds, strange rules, and journeys worth taking.'][index]+'</small></span><span class="genre-covers">'+titles.slice(0,3).map(function(story){return '<img src="'+coverFor(story)+'" alt="" width="76" height="110" loading="lazy">';}).join('')+'</span><span class="count">'+titles.length+' titles '+icon.arrow+'</span></a>';}).join('')+'</section>';
 observeReveals();
}

function shelfItem(story,type){return '<article class="shelf-item" data-reveal><a href="'+linkFor(story)+'"><img src="'+coverFor(story)+'" alt="'+story.title+' manga cover" width="124" height="186" loading="lazy"></a><div><span class="eyebrow">'+story.genre+'</span><h3><a href="'+linkFor(story)+'">'+story.title+'</a></h3><p>'+story.author+'</p><div class="card-actions"><a class="text-button" href="'+linkFor(story)+'">Open details</a><button class="remove-link" type="button" data-remove="'+story.id+'" data-remove-type="'+type+'">Remove</button></div></div></article>';}
function renderShelf(){
 const root=one('[data-shelf]');if(!root)return;const reader=currentReader();const likes=KOMA_STORIES.filter(function(story){return liked().indexOf(story.id)!==-1;}),reads=KOMA_STORIES.filter(function(story){return read().indexOf(story.id)!==-1;});
 const intro='<section class="page-intro" data-reveal><span class="section-index">READER / PERSONAL LIBRARY</span><p class="kicker">Your reading record</p><h1 class="page-title">My shelf.</h1><p>A quiet place for titles you want to remember.</p></section>';
 if(!reader){root.innerHTML=intro+'<section class="profile-gate" data-reveal><div class="gate-mark">'+icon.heart+'</div><div><span class="eyebrow">No reader selected</span><h2>Make this shelf yours.</h2><p>Create a local reader profile to save manga and track the chapter you finish. Everything stays on this browser.</p><button class="button button--ink" type="button" data-profile-open>Create or log in '+icon.arrow+'</button></div></section>';observeReveals();return;}
 root.innerHTML=intro+'<section class="reader-summary" data-reveal><div><span class="eyebrow">Current reader</span><h2>'+escapeHTML(reader.name)+'</h2></div><dl><div><dt>'+likes.length+'</dt><dd>saved</dd></div><div><dt>'+reads.length+'</dt><dd>finished</dd></div></dl><button class="text-button" type="button" data-profile-open>Manage profile</button></section><div class="shelf-columns"><section class="shelf-panel"><div class="section-heading"><div><span class="section-index">01 / KEEP CLOSE</span><h2>Saved</h2></div><p>'+likes.length+' title'+(likes.length===1?'':'s')+'</p></div><div class="shelf-list">'+(likes.length?likes.map(function(story){return shelfItem(story,'liked');}).join(''):'<div class="empty-state"><strong>Your saved shelf is empty.</strong><span>Tap Save on any manga to keep it here.</span><a class="button" href="browse.html">Browse stories</a></div>')+'</div></section><section class="shelf-panel"><div class="section-heading"><div><span class="section-index">02 / READING LOG</span><h2>Finished</h2></div><p>'+reads.length+' title'+(reads.length===1?'':'s')+'</p></div><div class="shelf-list">'+(reads.length?reads.map(function(story){return shelfItem(story,'read');}).join(''):'<div class="empty-state"><strong>Nothing marked complete.</strong><span>Finish the featured chapter and add it to your reading log.</span><a class="button" href="stories/story-01.html">Open featured story</a></div>')+'</div></section></div>';
 observeReveals();
}

function renderAbout(){
 const root=one('[data-about]');if(!root)return;
 root.innerHTML='<section class="about-intro" data-reveal><span class="edition-mark">ABOUT KOMA <b>コマ</b></span><p class="kicker">ITE Project · BSIT 21010</p><h1 class="about-quote">Stories deserve a better way to be <i>discovered.</i></h1><p>KOMA is a manga-library concept that treats browsing like opening a good magazine: visual, focused, and built around curiosity instead of clutter.</p></section><section class="about-grid"><article class="owner-card" aria-labelledby="owner-title" data-reveal><span class="eyebrow">Designed & developed by</span><h2 id="owner-title">Sachi DelaCruz</h2><p>A second-year BSIT student at Bestlink College of the Philippines.</p><dl><div><dt>Section</dt><dd>BSIT 21010</dd></div><div><dt>Project</dt><dd>ITE · 2026</dd></div></dl></article><article class="about-manifesto" data-reveal><span class="section-index">THE IDEA</span><h2>Less noise. More “I need to read that.”</h2><p>Every title gets room to breathe: a strong cover, a clear mood, an original synopsis, and a direct path to details.</p><p>KOMA does not reproduce manga chapters or host unofficial scans. Its single reading link continues on an official publisher source.</p></article></section><section class="rules" aria-label="KOMA principles"><article class="rule" data-reveal><span class="rule-num">01</span><div><strong>Curated discovery</strong><p>Thirty intentional picks are easier to love than an endless wall of recommendations.</p></div></article><article class="rule" data-reveal><span class="rule-num">02</span><div><strong>Useful interaction</strong><p>Search, filter, save, mark as read, switch themes, and build a local reader shelf.</p></div></article><article class="rule" data-reveal><span class="rule-num">03</span><div><strong>Respect the work</strong><p>Cover credits remain with creators and publishers. Reading continues through official sources.</p></div></article></section><section class="colophon" data-reveal><div><span class="section-index">COLOPHON</span><h2>Built with the basics, finished with intention.</h2><p>Plain HTML, CSS, and JavaScript. No framework, no copied UI kit, no unnecessary dependencies.</p></div><div class="font-samples"><p class="f-display">Dela Gothic One</p><p class="f-body">Zen Kaku Gothic New</p><p class="f-label">DOTGOTHIC16</p></div><div class="swatches"><span class="swatch paper" title="Paper"></span><span class="swatch ink" title="Ink"></span><span class="swatch spot" title="Vermilion"></span></div></section><section class="image-credits"><strong>Image credits.</strong> Manga cover art remains © its respective creators and publishers. Covers are shown for this educational project. The featured reading link opens MANGA Plus by SHUEISHA.</section>';
 observeReveals();
}

function renderStory(){
 const root=one('[data-story]');if(!root)return;const story=KOMA_STORIES.find(function(item){return item.id===document.body.dataset.storyId;});if(!story){root.innerHTML='<div class="empty-state">That manga panel could not be found.</div>';return;}document.title=story.title+' — KOMA';
 const state=story.hasChapter?'<div class="chapter-row is-available"><span><b>01</b>'+story.chapter+'</span><small>AVAILABLE NOW</small></div><div class="chapter-row is-pending" aria-disabled="true"><span><b>02</b>More chapters</span><small>NOT LISTED</small></div>':'<div class="chapter-row is-pending" aria-disabled="true"><span><b>—</b>No chapter link listed</span><small>DISCOVERY ONLY</small></div>';
 const action=story.hasChapter?'<a class="button button--spot" href="'+story.readUrl+'" target="_blank" rel="noopener noreferrer">Read on '+story.sourceName+' '+icon.external+'</a><button class="button button--quiet" type="button" data-mark-read="'+story.id+'">'+(read().indexOf(story.id)!==-1?'Marked as finished':'Mark as finished')+'</button><p class="reader-note">The official chapter opens in a new tab.</p>':'<button class="button" type="button" disabled aria-disabled="true">No official link listed</button><p class="reader-note">This profile is for discovery. KOMA does not host or reproduce manga pages.</p>';
 root.innerHTML='<div class="story-topbar"><a class="back-link" href="../browse.html">← Back to library</a><span>INDEX / '+story.id+' OF '+KOMA_STORIES.length+'</span></div><article class="story-hero" data-reveal><div class="story-art"><img class="story-cover" src="'+coverFor(story)+'" alt="'+story.title+' manga cover" width="600" height="900" fetchpriority="high"><span class="story-index">'+story.id+'</span></div><div class="story-meta"><span class="kicker">'+(story.hasChapter?'Featured selection':'KOMA selection')+'</span><h1 class="story-title">'+story.title+'</h1><p class="byline">Story & art by <strong>'+story.author+'</strong></p><span class="tag">'+story.genre+'</span><p class="story-deck">'+story.synopsis+'</p><div class="story-actions story-actions--space"><button class="like-button '+(isLiked(story.id)?'is-liked':'')+'" type="button" data-like="'+story.id+'" aria-pressed="'+isLiked(story.id)+'">'+icon.heart+'<span>'+(isLiked(story.id)?'Saved to shelf':'Save to shelf')+'</span></button></div></div></article><div class="story-layout"><section class="synopsis-box" data-reveal><span class="section-index">01 / OVERVIEW</span><div class="section-heading"><div><h2>Why it belongs here</h2></div><button class="text-button" type="button" data-synopsis-toggle>Hide</button></div><p data-synopsis-copy>'+story.synopsis+'</p></section><aside class="chapters-panel" data-reveal><span class="section-index">02 / AVAILABILITY</span><h2>Chapters</h2>'+state+'</aside></div><section class="reader-panel" data-reveal><div><span class="eyebrow">'+(story.hasChapter?'A first-page feeling':'Discovery note')+'</span><h2>'+ (story.hasChapter?story.chapter:'Read it from the source')+'</h2><p class="chapter-preview">'+(story.hasChapter?story.preview:'KOMA gives you the cover, creator, genre, and a concise original synopsis—enough to decide whether this story deserves a place on your list.')+'</p></div><div class="story-actions story-actions--reader">'+action+'</div></section><section class="next-story" data-reveal><span class="eyebrow">Keep browsing</span><h2>Not your mood? There are twenty-nine more.</h2><a class="button button--ink" href="../browse.html">Return to all titles '+icon.arrow+'</a></section><p class="reader-note story-credit">Cover art © its respective owners. Shown for educational use only.</p>';
 observeReveals();
}

let opener=null;
function openModal(id,button){
 const story=KOMA_STORIES.find(function(item){return item.id===id;});if(!story)return;opener=button;const modal=one('#book-modal');const action=story.hasChapter?'<a class="button button--ink" href="'+linkFor(story)+'">View Chapter 1 '+icon.arrow+'</a>':'<a class="button" href="'+linkFor(story)+'">View details '+icon.arrow+'</a>';
 modal.innerHTML='<div class="modal-dialog" role="dialog" aria-modal="true" aria-labelledby="modal-title" tabindex="-1"><button class="icon-button modal-close" type="button" data-close-modal aria-label="Close details">'+icon.close+'</button><div class="modal-content"><div class="modal-cover"><img src="'+coverFor(story)+'" alt="'+story.title+' manga cover" width="600" height="900"><span>'+story.id+' / '+KOMA_STORIES.length+'</span></div><div class="modal-copy"><span class="tag">'+story.genre+'</span><h2 id="modal-title">'+story.title+'</h2><p class="byline">Story & art by '+story.author+'</p><p>'+story.synopsis+'</p><p class="availability '+(story.hasChapter?'is-available':'is-pending')+'">'+(story.hasChapter?'Chapter 01 live':'Discovery only')+'</p><div class="button-row"><button class="like-button '+(isLiked(story.id)?'is-liked':'')+'" type="button" data-like="'+story.id+'">'+icon.heart+'<span>'+(isLiked(story.id)?'Saved':'Save')+'</span></button>'+action+'</div></div></div></div>';
 modal.hidden=false;document.body.classList.add('no-scroll');one('.modal-dialog',modal).focus();
}
function closeModal(){const modal=one('#book-modal');if(!modal||modal.hidden)return;modal.hidden=true;modal.innerHTML='';document.body.classList.remove('no-scroll');if(opener)opener.focus();}
let profileOpener=null;
function profileDialogContent(){
 const reader=currentReader(),profiles=readerProfiles();
 if(reader){return '<div class="reader-dialog" role="dialog" aria-modal="true" aria-labelledby="reader-title" tabindex="-1"><button class="icon-button modal-close" type="button" data-profile-close aria-label="Close reader profile">'+icon.close+'</button><div class="reader-dialog-copy"><span class="eyebrow">Current reader</span><h2 id="reader-title">Hey, '+escapeHTML(reader.name)+'.</h2><p>Your KOMA shelf lives on this browser.</p><div class="reader-totals"><span><b>'+liked().length+'</b> saved</span><span><b>'+read().length+'</b> finished</span></div><div class="button-row"><a class="button button--ink" href="'+prefix+'shelf.html">Open my shelf</a><button class="button button--quiet" type="button" data-profile-signout>Log out</button></div><button class="text-button switch-reader" type="button" data-profile-switch>Switch reader</button><p class="local-note">Local profile only. It does not sync to another device or create an online account.</p></div></div>';}
 const savedChoices=profiles.length?'<div class="saved-reader-list"><p class="eyebrow">Continue as</p>'+profiles.map(function(profile){return '<button class="saved-reader" type="button" data-profile-choose="'+profile.id+'"><span>'+escapeHTML(profile.name)+'</span>'+icon.arrow+'</button>';}).join('')+'</div>':'';
 return '<div class="reader-dialog" role="dialog" aria-modal="true" aria-labelledby="reader-title" tabindex="-1"><button class="icon-button modal-close" type="button" data-profile-close aria-label="Close reader profile">'+icon.close+'</button><div class="reader-dialog-copy"><span class="eyebrow">Reader profile</span><h2 id="reader-title">Make your shelf yours.</h2><p>Save manga and keep a simple reading log on this browser.</p>'+savedChoices+'<div class="form-divider"><span>New reader</span></div><form class="reader-form" data-profile-create><label for="reader-name">Display name</label><input id="reader-name" name="name" type="text" maxlength="36" required autocomplete="nickname" placeholder="What should we call you?"><label for="reader-pin">4-digit passcode</label><input id="reader-pin" name="pin" type="password" inputmode="numeric" pattern="[0-9]{4}" maxlength="4" required autocomplete="new-password" placeholder="••••"><p class="form-message" data-profile-message aria-live="polite"></p><button class="button button--ink" type="submit">Create reader profile '+icon.arrow+'</button></form><p class="local-note">Local profile only. Your passcode and shelf stay on this device.</p></div></div>';
}
function profileLoginContent(profile){return '<div class="reader-dialog" role="dialog" aria-modal="true" aria-labelledby="reader-title" tabindex="-1"><button class="icon-button modal-close" type="button" data-profile-close aria-label="Close reader profile">'+icon.close+'</button><div class="reader-dialog-copy"><button class="text-button dialog-back" type="button" data-profile-back>← All readers</button><span class="eyebrow">Welcome back</span><h2 id="reader-title">'+escapeHTML(profile.name)+'</h2><p>Enter your local 4-digit passcode to open this shelf.</p><form class="reader-form" data-profile-login data-profile-id="'+profile.id+'"><label for="login-pin">Passcode</label><input id="login-pin" name="pin" type="password" inputmode="numeric" pattern="[0-9]{4}" maxlength="4" required autocomplete="current-password" placeholder="••••" autofocus><p class="form-message" data-profile-message aria-live="polite"></p><button class="button button--ink" type="submit">Open my shelf '+icon.arrow+'</button></form><p class="local-note">This is a browser-only profile, not an online account.</p></div></div>';}
function openProfile(button){profileOpener=button||document.activeElement;const modal=one('#reader-modal');if(!modal)return;modal.innerHTML=profileDialogContent();modal.hidden=false;document.body.classList.add('no-scroll');const dialog=one('.reader-dialog',modal);dialog.focus();}
function closeProfile(){const modal=one('#reader-modal');if(!modal||modal.hidden)return;modal.hidden=true;modal.innerHTML='';document.body.classList.remove('no-scroll');if(profileOpener&&typeof profileOpener.focus==='function')profileOpener.focus();}
function refreshProfile(){renderChrome();repaint();}
function createProfile(form){const name=form.elements.name.value.trim(),pin=form.elements.pin.value.trim(),message=one('[data-profile-message]',form);if(!name||!/^[0-9]{4}$/.test(pin)){if(message)message.textContent='Add a name and exactly four numbers.';return;}if(readerProfiles().some(function(profile){return profile.name.toLowerCase()===name.toLowerCase();})){if(message)message.textContent='That reader name already exists on this browser.';return;}const profiles=readerProfiles();const profile={id:'r'+Date.now().toString(36)+Math.random().toString(36).slice(2,7),name:name,pinHash:profileHash(name+'::'+pin)};STORE.set(PROFILE_KEY,profiles.concat([profile]));STORE.set(ACTIVE_PROFILE_KEY,profile.id);refreshProfile();openProfile(profileOpener);}
function chooseProfile(id){const profile=readerProfiles().find(function(item){return item.id===id;});if(!profile)return;const modal=one('#reader-modal');modal.innerHTML=profileLoginContent(profile);const input=one('#login-pin',modal);if(input)input.focus();}
function loginProfile(form){const profile=readerProfiles().find(function(item){return item.id===form.dataset.profileId;}),pin=form.elements.pin.value.trim(),message=one('[data-profile-message]',form);if(!profile)return;if(profile.pinHash!==profileHash(profile.name+'::'+pin)){if(message)message.textContent='That passcode does not match. Try again.';form.elements.pin.select();return;}STORE.set(ACTIVE_PROFILE_KEY,profile.id);refreshProfile();openProfile(profileOpener);}
function signOut(){STORE.set(ACTIVE_PROFILE_KEY,'');refreshProfile();openProfile(profileOpener);}
function repaint(){if(page==='home')renderHome();if(page==='browse')renderBrowse();if(page==='genres')renderGenres();if(page==='shelf')renderShelf();if(page==='about')renderAbout();if(page==='story')renderStory();}
function toggleLike(id,button){const key=readerStoreKey('liked');if(!key){openProfile(button);return;}const set=liked();STORE.set(key,set.indexOf(id)!==-1?set.filter(function(item){return item!==id;}):set.concat([id]));repaint();}
function markRead(id,button){const key=readerStoreKey('read');if(!key){openProfile(button);return;}const set=read();if(set.indexOf(id)===-1)STORE.set(key,set.concat([id]));repaint();}
function remove(id,type){const key=readerStoreKey(type==='liked'?'liked':'read');if(!key)return;STORE.set(key,STORE.get(key,[]).filter(function(item){return item!==id;}));renderShelf();}
let revealObserver=null;
function observeReveals(){
 const items=all('[data-reveal]:not(.is-visible)');if(!items.length)return;
 if(!('IntersectionObserver' in window)||window.matchMedia('(prefers-reduced-motion: reduce)').matches){items.forEach(function(item){item.classList.add('is-visible');});return;}
 if(!revealObserver){revealObserver=new IntersectionObserver(function(entries){entries.forEach(function(entry){if(entry.isIntersecting){entry.target.classList.add('is-visible');revealObserver.unobserve(entry.target);}});},{rootMargin:'0px 0px -7% 0px',threshold:.08});}
 items.forEach(function(item){revealObserver.observe(item);});
}
function updateScrollProgress(){const progress=one('[data-scroll-progress]'),up=one('[data-scroll-top]'),down=one('[data-scroll-bottom]');const max=Math.max(0,document.documentElement.scrollHeight-window.innerHeight);const position=Math.max(0,window.scrollY||document.documentElement.scrollTop);const ratio=max>0?position/max:0;if(progress)progress.style.transform='scaleX('+Math.min(1,Math.max(0,ratio))+')';if(up)up.hidden=max<320||position<160;if(down)down.hidden=max<320||max-position<160;}
function jumpTo(position){const reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches;window.scrollTo({top:position==='top'?0:document.documentElement.scrollHeight,behavior:reduced?'auto':'smooth'});}

document.addEventListener('click',function(event){
 if(event.target.closest('[data-scroll-top]')){jumpTo('top');return;}
 if(event.target.closest('[data-scroll-bottom]')){jumpTo('bottom');return;}
 const theme=event.target.closest('[data-theme-toggle]');if(theme){const night=document.documentElement.dataset.theme!=='night';document.documentElement.dataset.theme=night?'night':'';try{localStorage.setItem('koma-theme',night?'night':'day');}catch(error){}theme.innerHTML=night?icon.sun:icon.moon;theme.setAttribute('aria-pressed',night);theme.setAttribute('aria-label','Switch to '+(night?'light':'dark')+' theme');return;}
 const profileOpen=event.target.closest('[data-profile-open]');if(profileOpen){openProfile(profileOpen);return;}
 if(event.target.closest('[data-profile-close]')){closeProfile();return;}
 const choose=event.target.closest('[data-profile-choose]');if(choose){chooseProfile(choose.dataset.profileChoose);return;}
 if(event.target.closest('[data-profile-back]')){const modal=one('#reader-modal');modal.innerHTML=profileDialogContent();one('.reader-dialog',modal).focus();return;}
 if(event.target.closest('[data-profile-signout]')){signOut();return;}
 if(event.target.closest('[data-profile-switch]')){STORE.set(ACTIVE_PROFILE_KEY,'');refreshProfile();openProfile(profileOpener);return;}
 const like=event.target.closest('[data-like]');if(like){toggleLike(like.dataset.like,like);return;}
 const details=event.target.closest('[data-details]');if(details){openModal(details.dataset.details,details);return;}
 if(event.target.closest('[data-close-modal]')){closeModal();return;}
 const mark=event.target.closest('[data-mark-read]');if(mark){markRead(mark.dataset.markRead,mark);return;}
 const removed=event.target.closest('[data-remove]');if(removed){remove(removed.dataset.remove,removed.dataset.removeType);return;}
 const toggle=event.target.closest('[data-synopsis-toggle]');if(toggle){const copy=one('[data-synopsis-copy]');copy.hidden=!copy.hidden;toggle.textContent=copy.hidden?'Show':'Hide';}
 if(event.target.id==='reader-modal'){closeProfile();}
});
document.addEventListener('submit',function(event){const create=event.target.closest('[data-profile-create]'),login=event.target.closest('[data-profile-login]');if(create){event.preventDefault();createProfile(create);}if(login){event.preventDefault();loginProfile(login);}});
document.addEventListener('keydown',function(event){const modal=one('#book-modal'),profileModal=one('#reader-modal');if(event.key==='Escape'){closeModal();closeProfile();}if(event.key==='Tab'&&modal&&!modal.hidden){const focus=all('button,a[href]',modal).filter(function(item){return !item.disabled;});if(!focus.length)return;const first=focus[0],last=focus[focus.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}if(event.key==='Tab'&&profileModal&&!profileModal.hidden){const focus=all('button,input,select',profileModal).filter(function(item){return !item.disabled;});if(!focus.length)return;const first=focus[0],last=focus[focus.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}});
one('#book-modal')&&one('#book-modal').addEventListener('click',function(event){if(event.target.id==='book-modal')closeModal();});
one('#reader-modal')&&one('#reader-modal').addEventListener('click',function(event){if(event.target.id==='reader-modal')closeProfile();});

renderChrome();
repaint();
observeReveals();
updateScrollProgress();
window.addEventListener('scroll',updateScrollProgress,{passive:true});
window.addEventListener('resize',updateScrollProgress);

